sourcesContent:
.top-bar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 50px;
  background: var(--bg-header);
  border-bottom: 1px solid var(--border-light);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  z-index: 100;
}

/* Kiri: User Info */
.user-info {
  display: flex;
  align-items: center;
  gap: 10px;
}

.user-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid var(--border-light);
  background: var(--olive-primary);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-sm);
  font-weight: var(--font-bold);
  flex-shrink: 0;
}

.user-name {
  font-size: var(--text-base);
  font-weight: var(--font-semibold);
  color: var(--text-primary);
  line-height: var(--leading-tight);
}

.user-role {
  font-size: var(--text-xs);
  color: var(--text-secondary);
  font-weight: var(--font-normal);
}

/* Tengah: Logo Sekolah + Judul */
.school-brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.school-logo {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #1E88E5;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.school-title {
  font-size: var(--text-lg);
  font-weight: var(--font-bold);
  color: var(--text-primary);
}

/* Kanan: Aplikasi Info */
.app-info {
  text-align: right;
}

.app-label {
  font-size: var(--text-xs);
  color: var(--text-secondary);
}

.app-name {
  font-size: var(--text-xl);
  font-weight: var(--font-bold);
  color: var(--text-primary);
  font-style: italic;
}

.clock {
  font-size: var(--text-base);
  color: var(--text-secondary);
  font-family: 'Courier New', monospace;
  font-weight: var(--font-semibold);
}
